package vn.covie.moderation.application;
import java.util.List;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.covie.admin.security.AdminAccessPolicy;import vn.covie.moderation.api.dto.*;import vn.covie.moderation.model.*;import vn.covie.moderation.persistence.*;import vn.covie.shared.web.*;
@Service public class ModerationCaseService {private final AdminAccessPolicy access;private final ModerationCaseRepository cases;private final ModerationActionRepository actions;public ModerationCaseService(AdminAccessPolicy a,ModerationCaseRepository c,ModerationActionRepository x){access=a;cases=c;actions=x;}@Transactional(readOnly=true)public Page<ModerationCaseSummaryResponse> page(int page,int size,ModerationCaseStatus status,String sort){access.requireAdmin();if(page<0||size<1||size>100)throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Moderation page or size is invalid.");Sort s=switch(sort==null?"OPENED_DESC":sort){case "OPENED_DESC"->Sort.by(Sort.Direction.DESC,"openedAt", "id");case "OPENED_ASC"->Sort.by(Sort.Direction.ASC,"openedAt", "id");case "RESOLVED_DESC"->Sort.by(Sort.Direction.DESC,"resolvedAt", "id");default->throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Moderation sort is invalid.");};Pageable p=PageRequest.of(page,size,s);return(status==null?cases.findAll(p):cases.findAllByCaseStatus(status,p)).map(this::map);}@Transactional(readOnly=true)public ModerationCaseDetailResponse detail(UUID id){access.requireAdmin();var c=cases.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Moderation case was not found."));List<ModerationActionResponse> history=actions.findAllByModerationCaseIdOrderByCreatedAtAscIdAsc(id).stream().map(a->new ModerationActionResponse(a.getId(),a.getActionType(),a.getActorAdminUserId(),a.getReasonCode(),a.getNote(),a.getCreatedAt())).toList();return new ModerationCaseDetailResponse(map(c),history);}private ModerationCaseSummaryResponse map(ModerationCaseEntity c){return new ModerationCaseSummaryResponse(c.getId(),c.getCaseType(),c.getCaseStatus(),c.getTargetType(),c.target().id(),c.getReasonCode(),c.getOpenedAt(),c.getResolvedAt());}}
